#pragma once#include "BaseReader.h"class KMUL : public KBaseReader{public:  KMUL(){}  virtual std::string GetType() const  {    return "MUL";  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc )  {    return FALSE;  }};//////////////////////////////////////////////////////////////////////////class KMULFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new KMUL();    return ptr;  }};